class ResourceDayTimeColsJoiner extends VResourceJoiner {
    transformSeg(seg, resourceDayTable, resourceI) {
        let dateI = seg.col;
        let col = resourceDayTable.computeCol(dateI, resourceI);
        if (col === -1) {
            return [];
        }
        return [
            {
                ...seg,
                col,
            },
        ];
    }
}

